    UnmapRfid
  },
  data() {
    return {
      membersUpdate: false,
      rfidMapping: false,
      membersItem: {},
      search: "",
      SnackBarComponent: {},
      CommonVuetifyObj: {},
      tableData: [],
      nextToken: null,
