      if (this.nextToken) {
        this.get_users();
      }
    },
    get_date(date) {
      return formatedatetime(date);
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.tableData = [];
      this.membersUpdate = false;
      this.rfidMapping = false;
      this.get_users();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    handle_row_click(click, val) {
      this.membersItem = val.item;
      this.componentCheck = 1;
      this.membersUpdate = true;
    },
    click_edit(val) {
      this.membersItem = val;
      this.componentCheck = 1;
      this.membersUpdate = true;
    },
    unmap_userrfid(val) {
      this.membersItem = val;
      this.componentCheck = 2;
      this.rfidMapping = true;
    },
    async get_users() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_all_users, {
          input: {
            limit: 500,
            nextToken: this.nextToken
          }
        }));
        this.tableLoading = false;
        let response = result.data.list_all_users;
        if (typeof response === "string") {
          response = JSON.parse(response);
        }
        if (response.Status === "SUCCESS") {
          let dataArray = response.data || [];
          this.nextToken = response.nextToken;
          let array = this.tableData.concat(dataArray);
          this.tableData = array;
          const uniqueArrayOfObjects = this.tableData.filter((obj, index, self) => index === self.findIndex(o => o.user_id === obj.user_id));
          this.tableData = uniqueArrayOfObjects;
          this.tableData.sort((a, b) => {
            return a.full_user_name.localeCompare(b.full_user_name);
          });
          this.paginateData();
          this.totalItems = this.tableData.length;
        } else {
          this.tableData = [];
          this.totalItems = 0;
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.message || "Failed to fetch users",
          timeout: 5000,
          Top: true
        };
      }
    },
    updatePageItems(newPage) {
      this.currentPage = newPage;
    },
    paginateData() {
      this.pageCount = Math.ceil(this.tableData.length / this.itemsPerPage);
    },
    handleSortChange(newSortBy) {
      this.sortBy = newSortBy;
    },
    getSortValue(value, key) {
      if (typeof value === "object" && key in value) {
        return value[key];
      }
      return value;
    }
  }
};
